insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('2pe-2-2','2pe','베드로후서',2,2,'여럿이 그들의 호색하는 것을 따르리니 이로 말미암아 진리의 도가 비방을 받을 것이요',30501),
('2pe-2-3','2pe','베드로후서',2,3,'그들이 탐심으로써 지어낸 말을 가지고 너희로 이득을 삼으니 그들의 심판은 옛적부터 지체하지 아니하며 그들의 멸망은 잠들지 아니하느니라',30502),
('2pe-2-4','2pe','베드로후서',2,4,'하나님이 범죄한 천사들을 용서하지 아니하시고 지옥에 던져 어두운 구덩이에 두어 심판 때까지 지키게 하셨으며',30503),
('2pe-2-5','2pe','베드로후서',2,5,'옛 세상을 용서하지 아니하시고 오직 의를 전파하는 노아와 그 일곱 식구를 보존하시고 경건하지 아니한 자들의 세상에 홍수를 내리셨으며',30504),
('2pe-2-6','2pe','베드로후서',2,6,'소돔과 고모라 성을 멸망하기로 정하여 재가 되게 하사 후세에 경건하지 아니할 자들에게 본을 삼으셨으며',30505),
('2pe-2-7','2pe','베드로후서',2,7,'무법한 자들의 음란한 행실로 말미암아 고통 당하는 의로운 롯을 건지셨으니',30506),
('2pe-2-8','2pe','베드로후서',2,8,'(이는 이 의인이 그들 중에 거하여 날마다 저 불법한 행실을 보고 들음으로 그 의로운 심령이 상함이라)',30507),
('2pe-2-9','2pe','베드로후서',2,9,'주께서 경건한 자는 시험에서 건지실 줄 아시고 불의한 자는 형벌 아래에 두어 심판 날까지 지키시며',30508),
('2pe-2-10','2pe','베드로후서',2,10,'특별히 육체를 따라 더러운 정욕 가운데서 행하며 주관하는 이를 멸시하는 자들에게는 형벌할 줄 아시느니라 이들은 당돌하고 자긍하며 떨지 않고 영광 있는 자들을 비방하거니와',30509),
('2pe-2-11','2pe','베드로후서',2,11,'더 큰 힘과 능력을 가진 천사들도 주 앞에서 그들을 거슬러 비방하는 고발을 하지 아니하느니라',30510),
('2pe-2-12','2pe','베드로후서',2,12,'그러나 이 사람들은 본래 잡혀 죽기 위하여 난 이성 없는 짐승 같아서 그 알지 못하는 것을 비방하고 그들의 멸망 가운데서 멸망을 당하며',30511),
('2pe-2-13','2pe','베드로후서',2,13,'불의의 값으로 불의를 당하며 낮에 즐기고 노는 것을 기쁘게 여기는 자들이니 점과 흠이라 너희와 함께 연회할 때에 그들의 속임수로 즐기고 놀며',30512),
('2pe-2-14','2pe','베드로후서',2,14,'음심이 가득한 눈을 가지고 범죄하기를 그치지 아니하고 굳세지 못한 영혼들을 유혹하며 탐욕에 연단된 마음을 가진 자들이니 저주의 자식이라',30513),
('2pe-2-15','2pe','베드로후서',2,15,'그들이 바른 길을 떠나 미혹되어 브올의 아들 발람의 길을 따르는도다 그는 불의의 삯을 사랑하다가',30514),
('2pe-2-16','2pe','베드로후서',2,16,'자기의 불법으로 말미암아 책망을 받되 말하지 못하는 나귀가 사람의 소리로 말하여 이 선지자의 미친 행동을 저지하였느니라',30515),
('2pe-2-17','2pe','베드로후서',2,17,'이 사람들은 물 없는 샘이요 광풍에 밀려 가는 안개니 그들을 위하여 캄캄한 어둠이 예비되어 있나니',30516),
('2pe-2-18','2pe','베드로후서',2,18,'그들이 허탄한 자랑의 말을 토하며 그릇되게 행하는 사람들에게서 겨우 피한 자들을 음란으로써 육체의 정욕 중에서 유혹하는도다',30517),
('2pe-2-19','2pe','베드로후서',2,19,'그들에게 자유를 준다 하여도 자신들은 멸망의 종들이니 누구든지 진 자는 이긴 자의 종이 됨이라',30518),
('2pe-2-20','2pe','베드로후서',2,20,'만일 그들이 우리 주 되신 구주 예수 그리스도를 앎으로 세상의 더러움을 피한 후에 다시 그 중에 얽매이고 지면 그 나중 형편이 처음보다 더 심하리니',30519),
('2pe-2-21','2pe','베드로후서',2,21,'의의 도를 안 후에 받은 거룩한 명령을 저버리는 것보다 알지 못하는 것이 도리어 그들에게 나으니라',30520),
('2pe-2-22','2pe','베드로후서',2,22,'참된 속담에 이르기를 개가 그 토하였던 것에 돌아가고 돼지가 씻었다가 더러운 구덩이에 도로 누웠다 하는 말이 그들에게 응하였도다',30521),
('2pe-3-1','2pe','베드로후서',3,1,'사랑하는 자들아 내가 이제 이 둘째 편지를 너희에게 쓰노니 이 두 편지로 너희의 진실한 마음을 일깨워 생각나게 하여',30522),
('2pe-3-2','2pe','베드로후서',3,2,'곧 거룩한 선지자들이 예언한 말씀과 주 되신 구주께서 너희의 사도들로 말미암아 명하신 것을 기억하게 하려 하노라',30523),
('2pe-3-3','2pe','베드로후서',3,3,'먼저 이것을 알지니 말세에 조롱하는 자들이 와서 자기의 정욕을 따라 행하며 조롱하여',30524),
('2pe-3-4','2pe','베드로후서',3,4,'이르되 주께서 강림하신다는 약속이 어디 있느냐 조상들이 잔 후로부터 만물이 처음 창조될 때와 같이 그냥 있다 하니',30525),
('2pe-3-5','2pe','베드로후서',3,5,'이는 하늘이 옛적부터 있는 것과 땅이 물에서 나와 물로 성립된 것도 하나님의 말씀으로 된 것을 그들이 일부러 잊으려 함이로다',30526),
('2pe-3-6','2pe','베드로후서',3,6,'이로 말미암아 그 때에 세상은 물이 넘침으로 멸망하였으되',30527),
('2pe-3-7','2pe','베드로후서',3,7,'이제 하늘과 땅은 그 동일한 말씀으로 불사르기 위하여 보호하신 바 되어 경건하지 아니한 사람들의 심판과 멸망의 날까지 보존하여 두신 것이니라',30528),
('2pe-3-8','2pe','베드로후서',3,8,'사랑하는 자들아 주께는 하루가 천 년 같고 천 년이 하루 같다는 이 한 가지를 잊지 말라',30529),
('2pe-3-9','2pe','베드로후서',3,9,'주의 약속은 어떤 이들이 더디다고 생각하는 것 같이 더딘 것이 아니라 오직 주께서는 너희를 대하여 오래 참으사 아무도 멸망하지 아니하고 다 회개하기에 이르기를 원하시느니라',30530),
('2pe-3-10','2pe','베드로후서',3,10,'그러나 주의 날이 도둑 같이 오리니 그 날에는 하늘이 큰 소리로 떠나가고 물질이 뜨거운 불에 풀어지고 땅과 그 중에 있는 모든 일이 드러나리로다',30531),
('2pe-3-11','2pe','베드로후서',3,11,'이 모든 것이 이렇게 풀어지리니 너희가 어떠한 사람이 되어야 마땅하냐 거룩한 행실과 경건함으로',30532),
('2pe-3-12','2pe','베드로후서',3,12,'하나님의 날이 임하기를 바라보고 간절히 사모하라 그 날에 하늘이 불에 타서 풀어지고 물질이 뜨거운 불에 녹아지려니와',30533),
('2pe-3-13','2pe','베드로후서',3,13,'우리는 그의 약속대로 의가 있는 곳인 새 하늘과 새 땅을 바라보도다',30534),
('2pe-3-14','2pe','베드로후서',3,14,'그러므로 사랑하는 자들아 너희가 이것을 바라보나니 주 앞에서 점도 없고 흠도 없이 평강 가운데서 나타나기를 힘쓰라',30535),
('2pe-3-15','2pe','베드로후서',3,15,'또 우리 주의 오래 참으심이 구원이 될 줄로 여기라 우리가 사랑하는 형제 바울도 그 받은 지혜대로 너희에게 이같이 썼고',30536),
('2pe-3-16','2pe','베드로후서',3,16,'또 그 모든 편지에도 이런 일에 관하여 말하였으되 그 중에 알기 어려운 것이 더러 있으니 무식한 자들과 굳세지 못한 자들이 다른 성경과 같이 그것도 억지로 풀다가 스스로 멸망에 이르느니라',30537),
('2pe-3-17','2pe','베드로후서',3,17,'그러므로 사랑하는 자들아 너희가 이것을 미리 알았은즉 무법한 자들의 미혹에 이끌려 너희가 굳센 데서 떨어질까 삼가라',30538),
('2pe-3-18','2pe','베드로후서',3,18,'오직 우리 주 곧 구주 예수 그리스도의 은혜와 그를 아는 지식에서 자라 가라 영광이 이제와 영원한 날까지 그에게 있을지어다3)',30539),
('1jn-1-1','1jn','요한일서',1,1,'태초부터 있는 생명의 말씀에 관하여는 우리가 들은 바요 눈으로 본 바요 자세히 보고 우리의 손으로 만진 바라',30540),
('1jn-1-2','1jn','요한일서',1,2,'이 생명이 나타내신 바 된지라 이 영원한 생명을 우리가 보았고 증언하여 너희에게 전하노니 이는 아버지와 함께 계시다가 우리에게 나타내신 바 된 이시니라',30541),
('1jn-1-3','1jn','요한일서',1,3,'우리가 보고 들은 바를 너희에게도 전함은 너희로 우리와 사귐이 있게 하려 함이니 우리의 사귐은 아버지와 그의 아들 예수 그리스도와 더불어 누림이라',30542),
('1jn-1-4','1jn','요한일서',1,4,'우리가 이것을 씀은 우리의 기쁨이 충만하게 하려 함이라',30543),
('1jn-1-5','1jn','요한일서',1,5,'우리가 그에게서 듣고 너희에게 전하는 소식은 이것이니 곧 하나님은 빛이시라 그에게는 어둠이 조금도 없으시다는 것이니라',30544),
('1jn-1-6','1jn','요한일서',1,6,'만일 우리가 하나님과 사귐이 있다 하고 어둠에 행하면 거짓말을 하고 진리를 행하지 아니함이거니와',30545),
('1jn-1-7','1jn','요한일서',1,7,'그가 빛 가운데 계신 것 같이 우리도 빛 가운데 행하면 우리가 서로 사귐이 있고 그 아들 예수의 피가 우리를 모든 죄에서 깨끗하게 하실 것이요',30546),
('1jn-1-8','1jn','요한일서',1,8,'만일 우리가 죄가 없다고 말하면 스스로 속이고 또 진리가 우리 속에 있지 아니할 것이요',30547),
('1jn-1-9','1jn','요한일서',1,9,'만일 우리가 우리 죄를 자백하면 그는 미쁘시고 의로우사 우리 죄를 사하시며 우리를 모든 불의에서 깨끗하게 하실 것이요',30548),
('1jn-1-10','1jn','요한일서',1,10,'만일 우리가 범죄하지 아니하였다 하면 하나님을 거짓말하는 이로 만드는 것이니 또한 그의 말씀이 우리 속에 있지 아니하니라',30549),
('1jn-2-1','1jn','요한일서',2,1,'나의 자녀들아 내가 이것을 너희에게 씀은 너희로 죄를 범하지 않게 하려 함이라 만일 누가 죄를 범하여도 아버지 앞에서 우리에게 대언자가 있으니 곧 의로우신 예수 그리스도시라',30550),
('1jn-2-2','1jn','요한일서',2,2,'그는 우리 죄를 위한 화목 제물이니 우리만 위할 뿐 아니요 온 세상의 죄를 위하심이라',30551),
('1jn-2-3','1jn','요한일서',2,3,'우리가 그의 계명을 지키면 이로써 우리가 그를 아는 줄로 알 것이요',30552),
('1jn-2-4','1jn','요한일서',2,4,'그를 아노라 하고 그의 계명을 지키지 아니하는 자는 거짓말하는 자요 진리가 그 속에 있지 아니하되',30553),
('1jn-2-5','1jn','요한일서',2,5,'누구든지 그의 말씀을 지키는 자는 하나님의 사랑이 참으로 그 속에서 온전하게 되었나니 이로써 우리가 그의 안에 있는 줄을 아노라',30554),
('1jn-2-6','1jn','요한일서',2,6,'그의 안에 산다고 하는 자는 그가 행하시는 대로 자기도 행할지니라',30555),
('1jn-2-7','1jn','요한일서',2,7,'사랑하는 자들아 내가 새 계명을 너희에게 쓰는 것이 아니라 너희가 처음부터 가진 옛 계명이니 이 옛 계명은 너희가 들은 바 말씀이거니와',30556),
('1jn-2-8','1jn','요한일서',2,8,'다시 내가 너희에게 새 계명을 쓰노니 그에게와 너희에게도 참된 것이라 이는 어둠이 지나가고 참빛이 벌써 비침이니라',30557),
('1jn-2-9','1jn','요한일서',2,9,'빛 가운데 있다 하면서 그 형제를 미워하는 자는 지금까지 어둠에 있는 자요',30558),
('1jn-2-10','1jn','요한일서',2,10,'그의 형제를 사랑하는 자는 빛 가운데 거하여 자기 속에 거리낌이 없으나',30559),
('1jn-2-11','1jn','요한일서',2,11,'그의 형제를 미워하는 자는 어둠에 있고 또 어둠에 행하며 갈 곳을 알지 못하나니 이는 그 어둠이 그의 눈을 멀게 하였음이라',30560),
('1jn-2-12','1jn','요한일서',2,12,'자녀들아 내가 너희에게 쓰는 것은 너희 죄가 그의 이름으로 말미암아 사함을 받았음이요',30561),
('1jn-2-13','1jn','요한일서',2,13,'아비들아 내가 너희에게 쓰는 것은 너희가 태초부터 계신 이를 알았음이요 청년들아 내가 너희에게 쓰는 것은 너희가 악한 자를 이기었음이라',30562),
('1jn-2-14','1jn','요한일서',2,14,'아이들아 내가 너희에게 쓴 것은 너희가 아버지를 알았음이요 아비들아 내가 너희에게 쓴 것은 너희가 태초부터 계신 이를 알았음이요 청년들아 내가 너희에게 쓴 것은 너희가 강하고 하나님의 말씀이 너희 안에 거하시며 너희가 흉악한 자를 이기었음이라',30563),
('1jn-2-15','1jn','요한일서',2,15,'이 세상이나 세상에 있는 것들을 사랑하지 말라 누구든지 세상을 사랑하면 아버지의 사랑이 그 안에 있지 아니하니',30564),
('1jn-2-16','1jn','요한일서',2,16,'이는 세상에 있는 모든 것이 육신의 정욕과 안목의 정욕과 이생의 자랑이니 다 아버지께로부터 온 것이 아니요 세상으로부터 온 것이라',30565),
('1jn-2-17','1jn','요한일서',2,17,'이 세상도, 그 정욕도 지나가되 오직 하나님의 뜻을 행하는 자는 영원히 거하느니라',30566),
('1jn-2-18','1jn','요한일서',2,18,'아이들아 지금은 마지막 때라 적그리스도가 오리라는 말을 너희가 들은 것과 같이 지금도 많은 적그리스도가 일어났으니 그러므로 우리가 마지막 때인 줄 아노라',30567),
('1jn-2-19','1jn','요한일서',2,19,'그들이 우리에게서 나갔으나 우리에게 속하지 아니하였나니 만일 우리에게 속하였더라면 우리와 함께 거하였으려니와 그들이 나간 것은 다 우리에게 속하지 아니함을 나타내려 함이니라',30568),
('1jn-2-20','1jn','요한일서',2,20,'너희는 거룩하신 자에게서 기름 부음을 받고 모든 것을 아느니라',30569),
('1jn-2-21','1jn','요한일서',2,21,'내가 너희에게 쓰는 것은 너희가 진리를 알지 못하기 때문이 아니라 알기 때문이요 또 모든 거짓은 진리에서 나지 않기 때문이라',30570),
('1jn-2-22','1jn','요한일서',2,22,'거짓말하는 자가 누구냐 예수께서 그리스도이심을 부인하는 자가 아니냐 아버지와 아들을 부인하는 그가 적그리스도니',30571),
('1jn-2-23','1jn','요한일서',2,23,'아들을 부인하는 자에게는 또한 아버지가 없으되 아들을 시인하는 자에게는 아버지도 있느니라',30572),
('1jn-2-24','1jn','요한일서',2,24,'너희는 처음부터 들은 것을 너희 안에 거하게 하라 처음부터 들은 것이 너희 안에 거하면 너희가 아들과 아버지 안에 거하리라',30573),
('1jn-2-25','1jn','요한일서',2,25,'그가 우리에게 약속하신 것은 이것이니 곧 영원한 생명이니라',30574),
('1jn-2-26','1jn','요한일서',2,26,'너희를 미혹하는 자들에 관하여 내가 이것을 너희에게 썼노라',30575),
('1jn-2-27','1jn','요한일서',2,27,'너희는 주께 받은 바 기름 부음이 너희 안에 거하나니 아무도 너희를 가르칠 필요가 없고 오직 그의 기름 부음이 모든 것을 너희에게 가르치며 또 참되고 거짓이 없으니 너희를 가르치신 그대로 주 안에 거하라',30576),
('1jn-2-28','1jn','요한일서',2,28,'자녀들아 이제 그의 안에 거하라 이는 주께서 나타내신 바 되면 그가 강림하실 때에 우리로 담대함을 얻어 그 앞에서 부끄럽지 않게 하려 함이라',30577),
('1jn-2-29','1jn','요한일서',2,29,'너희가 그가 의로우신 줄을 알면 의를 행하는 자마다 그에게서 난 줄을 알리라',30578),
('1jn-3-1','1jn','요한일서',3,1,'보라 아버지께서 어떠한 사랑을 우리에게 베푸사 하나님의 자녀라 일컬음을 받게 하셨는가, 우리가 그러하도다 그러므로 세상이 우리를 알지 못함은 그를 알지 못함이라',30579),
('1jn-3-2','1jn','요한일서',3,2,'사랑하는 자들아 우리가 지금은 하나님의 자녀라 장래에 어떻게 될지는 아직 나타나지 아니하였으나 그가 나타나시면 우리가 그와 같을 줄을 아는 것은 그의 참모습 그대로 볼 것이기 때문이니',30580),
('1jn-3-3','1jn','요한일서',3,3,'주를 향하여 이 소망을 가진 자마다 그의 깨끗하심과 같이 자기를 깨끗하게 하느니라',30581),
('1jn-3-4','1jn','요한일서',3,4,'죄를 짓는 자마다 불법을 행하나니 죄는 불법이라',30582),
('1jn-3-5','1jn','요한일서',3,5,'그가 우리 죄를 없애려고 나타나신 것을 너희가 아나니 그에게는 죄가 없느니라',30583),
('1jn-3-6','1jn','요한일서',3,6,'그 안에 거하는 자마다 범죄하지 아니하나니 범죄하는 자마다 그를 보지도 못하였고 그를 알지도 못하였느니라',30584),
('1jn-3-7','1jn','요한일서',3,7,'자녀들아 아무도 너희를 미혹하지 못하게 하라 의를 행하는 자는 그의 의로우심과 같이 의롭고',30585),
('1jn-3-8','1jn','요한일서',3,8,'죄를 짓는 자는 마귀에게 속하나니 마귀는 처음부터 범죄함이라 하나님의 아들이 나타나신 것은 마귀의 일을 멸하려 하심이라',30586),
('1jn-3-9','1jn','요한일서',3,9,'하나님께로부터 난 자마다 죄를 짓지 아니하나니 이는 하나님의 씨가 그의 속에 거함이요 그도 범죄하지 못하는 것은 하나님께로부터 났음이라',30587),
('1jn-3-10','1jn','요한일서',3,10,'이러므로 하나님의 자녀들과 마귀의 자녀들이 드러나나니 무릇 의를 행하지 아니하는 자나 또는 그 형제를 사랑하지 아니하는 자는 하나님께 속하지 아니하니라',30588),
('1jn-3-11','1jn','요한일서',3,11,'우리는 서로 사랑할지니 이는 너희가 처음부터 들은 소식이라',30589),
('1jn-3-12','1jn','요한일서',3,12,'가인 같이 하지 말라 그는 악한 자에게 속하여 그 아우를 죽였으니 어떤 이유로 죽였느냐 자기의 행위는 악하고 그의 아우의 행위는 의로움이라',30590),
('1jn-3-13','1jn','요한일서',3,13,'형제들아 세상이 너희를 미워하여도 이상히 여기지 말라',30591),
('1jn-3-14','1jn','요한일서',3,14,'우리는 형제를 사랑함으로 사망에서 옮겨 생명으로 들어간 줄을 알거니와 사랑하지 아니하는 자는 사망에 머물러 있느니라',30592),
('1jn-3-15','1jn','요한일서',3,15,'그 형제를 미워하는 자마다 살인하는 자니 살인하는 자마다 영생이 그 속에 거하지 아니하는 것을 너희가 아는 바라',30593),
('1jn-3-16','1jn','요한일서',3,16,'그가 우리를 위하여 목숨을 버리셨으니 우리가 이로써 사랑을 알고 우리도 형제들을 위하여 목숨을 버리는 것이 마땅하니라',30594),
('1jn-3-17','1jn','요한일서',3,17,'누가 이 세상의 재물을 가지고 형제의 궁핍함을 보고도 도와 줄 마음을 닫으면 하나님의 사랑이 어찌 그 속에 거하겠느냐',30595),
('1jn-3-18','1jn','요한일서',3,18,'자녀들아 우리가 말과 혀로만 사랑하지 말고 행함과 진실함으로 하자',30596),
('1jn-3-19','1jn','요한일서',3,19,'이로써 우리가 진리에 속한 줄을 알고 또 우리 마음을 주 앞에서 굳세게 하리니',30597),
('1jn-3-20','1jn','요한일서',3,20,'이는 우리 마음이 혹 우리를 책망할 일이 있어도 하나님은 우리 마음보다 크시고 모든 것을 아시기 때문이라',30598),
('1jn-3-21','1jn','요한일서',3,21,'사랑하는 자들아 만일 우리 마음이 우리를 책망할 것이 없으면 하나님 앞에서 담대함을 얻고',30599),
('1jn-3-22','1jn','요한일서',3,22,'무엇이든지 구하는 바를 그에게서 받나니 이는 우리가 그의 계명을 지키고 그 앞에서 기뻐하시는 것을 행함이라',30600),
