('1jn-5-9','1jn','요한일서',5,9,'만일 우리가 사람들의 증언을 받을진대 하나님의 증거는 더욱 크도다 하나님의 증거는 이것이니 그의 아들에 대하여 증언하신 것이니라',30632),
('1jn-5-10','1jn','요한일서',5,10,'하나님의 아들을 믿는 자는 자기 안에 증거가 있고 하나님을 믿지 아니하는 자는 하나님을 거짓말하는 자로 만드나니 이는 하나님께서 그 아들에 대하여 증언하신 증거를 믿지 아니하였음이라',30633),
('1jn-5-11','1jn','요한일서',5,11,'또 증거는 이것이니 하나님이 우리에게 영생을 주신 것과 이 생명이 그의 아들 안에 있는 그것이니라',30634),
('1jn-5-12','1jn','요한일서',5,12,'아들이 있는 자에게는 생명이 있고 하나님의 아들이 없는 자에게는 생명이 없느니라',30635),
('1jn-5-13','1jn','요한일서',5,13,'내가 하나님의 아들의 이름을 믿는 너희에게 이것을 쓰는 것은 너희로 하여금 너희에게 영생이 있음을 알게 하려 함이라',30636),
('1jn-5-14','1jn','요한일서',5,14,'그를 향하여 우리가 가진 바 담대함이 이것이니 그의 뜻대로 무엇을 구하면 들으심이라',30637),
('1jn-5-15','1jn','요한일서',5,15,'우리가 무엇이든지 구하는 바를 들으시는 줄을 안즉 우리가 그에게 구한 그것을 얻은 줄을 또한 아느니라',30638),
('1jn-5-16','1jn','요한일서',5,16,'누구든지 형제가 사망에 이르지 아니하는 죄 범하는 것을 보거든 구하라 그리하면 사망에 이르지 아니하는 범죄자들을 위하여 그에게 생명을 주시리라 사망에 이르는 죄가 있으니 이에 관하여 나는 구하라 하지 않노라',30639),
('1jn-5-17','1jn','요한일서',5,17,'모든 불의가 죄로되 사망에 이르지 아니하는 죄도 있도다',30640),
('1jn-5-18','1jn','요한일서',5,18,'하나님께로부터 난 자는 다 범죄하지 아니하는 줄을 우리가 아노라 하나님께로부터 나신 자가 그를 지키시매 악한 자가 그를 만지지도 못하느니라',30641),
('1jn-5-19','1jn','요한일서',5,19,'또 아는 것은 우리는 하나님께 속하고 온 세상은 악한 자 안에 처한 것이며',30642),
('1jn-5-20','1jn','요한일서',5,20,'또 아는 것은 하나님의 아들이 이르러 우리에게 지각을 주사 우리로 참된 자를 알게 하신 것과 또한 우리가 참된 자 곧 그의 아들 예수 그리스도 안에 있는 것이니 그는 참 하나님이시요 영생이시라',30643),
('1jn-5-21','1jn','요한일서',5,21,'자녀들아 너희 자신을 지켜 우상에게서 멀리하라',30644),
('2jn-1-1','2jn','요한이서',1,1,'장로인 나는 택하심을 받은 부녀와 그의 자녀들에게 편지하노니 내가 참으로 사랑하는 자요 나뿐 아니라 진리를 아는 모든 자도 그리하는 것은',30645),
('2jn-1-2','2jn','요한이서',1,2,'우리 안에 거하여 영원히 우리와 함께 할 진리로 말미암음이로다',30646),
('2jn-1-3','2jn','요한이서',1,3,'은혜와 긍휼과 평강이 하나님 아버지와 아버지의 아들 예수 그리스도께로부터 진리와 사랑 가운데서 우리와 함께 있으리라',30647),
('2jn-1-4','2jn','요한이서',1,4,'너의 자녀들 중에 우리가 아버지께 받은 계명대로 진리를 행하는 자를 내가 보니 심히 기쁘도다',30648),
('2jn-1-5','2jn','요한이서',1,5,'부녀여, 내가 이제 네게 구하노니 서로 사랑하자 이는 새 계명 같이 네게 쓰는 것이 아니요 처음부터 우리가 가진 것이라',30649),
('2jn-1-6','2jn','요한이서',1,6,'또 사랑은 이것이니 우리가 그 계명을 따라 행하는 것이요 계명은 이것이니 너희가 처음부터 들은 바와 같이 그 가운데서 행하라 하심이라',30650),
('2jn-1-7','2jn','요한이서',1,7,'미혹하는 자가 세상에 많이 나왔나니 이는 예수 그리스도께서 육체로 오심을 부인하는 자라 이런 자가 미혹하는 자요 적그리스도니',30651),
('2jn-1-8','2jn','요한이서',1,8,'너희는 스스로 삼가 우리가 일한 것을 잃지 말고 오직 온전한 상을 받으라',30652),
('2jn-1-9','2jn','요한이서',1,9,'지나쳐 그리스도의 교훈 안에 거하지 아니하는 자는 다 하나님을 모시지 못하되 교훈 안에 거하는 그 사람은 아버지와 아들을 모시느니라',30653),
('2jn-1-10','2jn','요한이서',1,10,'누구든지 이 교훈을 가지지 않고 너희에게 나아가거든 그를 집에 들이지도 말고 인사도 하지 말라',30654),
('2jn-1-11','2jn','요한이서',1,11,'그에게 인사하는 자는 그 악한 일에 참여하는 자임이라',30655),
('2jn-1-12','2jn','요한이서',1,12,'내가 너희에게 쓸 것이 많으나 종이와 먹으로 쓰기를 원하지 아니하고 오히려 너희에게 가서 대면하여 말하려 하니 이는 너희 기쁨을 충만하게 하려 함이라',30656),
('2jn-1-13','2jn','요한이서',1,13,'택하심을 받은 네 자매의 자녀들이 네게 문안하느니라',30657),
('3jn-1-1','3jn','요한삼서',1,1,'장로인 나는 사랑하는 가이오 곧 내가 참으로 사랑하는 자에게 편지하노라',30658),
('3jn-1-2','3jn','요한삼서',1,2,'사랑하는 자여 네 영혼이 잘됨 같이 네가 범사에 잘되고 강건하기를 내가 간구하노라',30659),
('3jn-1-3','3jn','요한삼서',1,3,'형제들이 와서 네게 있는 진리를 증언하되 네가 진리 안에서 행한다 하니 내가 심히 기뻐하노라',30660),
('3jn-1-4','3jn','요한삼서',1,4,'내가 내 자녀들이 진리 안에서 행한다 함을 듣는 것보다 더 기쁜 일이 없도다',30661),
('3jn-1-5','3jn','요한삼서',1,5,'사랑하는 자여 네가 무엇이든지 형제 곧 나그네 된 자들에게 행하는 것은 신실한 일이니',30662),
('3jn-1-6','3jn','요한삼서',1,6,'그들이 교회 앞에서 너의 사랑을 증언하였느니라 네가 하나님께 합당하게 그들을 전송하면 좋으리로다',30663),
('3jn-1-7','3jn','요한삼서',1,7,'이는 그들이 주의 이름을 위하여 나가서 이방인에게 아무 것도 받지 아니함이라',30664),
('3jn-1-8','3jn','요한삼서',1,8,'그러므로 우리가 이같은 자들을 영접하는 것이 마땅하니 이는 우리로 진리를 위하여 함께 일하는 자가 되게 하려 함이라',30665),
('3jn-1-9','3jn','요한삼서',1,9,'내가 두어 자를 교회에 썼으나 그들 중에 으뜸되기를 좋아하는 디오드레베가 우리를 맞아들이지 아니하니',30666),
('3jn-1-10','3jn','요한삼서',1,10,'그러므로 내가 가면 그 행한 일을 잊지 아니하리라 그가 악한 말로 우리를 비방하고도 오히려 부족하여 형제들을 맞아들이지도 아니하고 맞아들이고자 하는 자를 금하여 교회에서 내쫓는도다',30667),
('3jn-1-11','3jn','요한삼서',1,11,'사랑하는 자여 악한 것을 본받지 말고 선한 것을 본받으라 선을 행하는 자는 하나님께 속하고 악을 행하는 자는 하나님을 뵈옵지 못하였느니라',30668),
('3jn-1-12','3jn','요한삼서',1,12,'데메드리오는 뭇 사람에게도, 진리에게서도 증거를 받았으매 우리도 증언하노니 너는 우리의 증언이 참된 줄을 아느니라',30669),
('3jn-1-13','3jn','요한삼서',1,13,'내가 네게 쓸 것이 많으나 먹과 붓으로 쓰기를 원하지 아니하고',30670),
('3jn-1-14','3jn','요한삼서',1,14,'속히 보기를 바라노니 또한 우리가 대면하여 말하리라',30671),
('3jn-1-15','3jn','요한삼서',1,15,'평강이 네게 있을지어다 여러 친구가 네게 문안하느니라 너는 친구들의 이름을 들어 문안하라',30672),
('jud-1-1','jud','유다서',1,1,'예수 그리스도의 종이요 야고보의 형제인 유다는 부르심을 받은 자 곧 하나님 아버지 안에서 사랑을 얻고 예수 그리스도를 위하여 지키심을 받은 자들에게 편지하노라',30673),
('jud-1-2','jud','유다서',1,2,'긍휼과 평강과 사랑이 너희에게 더욱 많을지어다',30674),
('jud-1-3','jud','유다서',1,3,'사랑하는 자들아 우리가 일반으로 받은 구원에 관하여 내가 너희에게 편지하려는 생각이 간절하던 차에 성도에게 단번에 주신 믿음의 도를 위하여 힘써 싸우라는 편지로 너희를 권하여야 할 필요를 느꼈노니',30675),
('jud-1-4','jud','유다서',1,4,'이는 가만히 들어온 사람 몇이 있음이라 그들은 옛적부터 이 판결을 받기로 미리 기록된 자니 경건하지 아니하여 우리 하나님의 은혜를 도리어 방탕한 것으로 바꾸고 홀로 하나이신 주재 곧 우리 주 예수 그리스도를 부인하는 자니라',30676),
('jud-1-5','jud','유다서',1,5,'너희가 본래 모든 사실을 알고 있으나 내가 너희로 다시 생각나게 하고자 하노라 주께서 백성을 애굽에서 구원하여 내시고 후에 믿지 아니하는 자들을 멸하셨으며',30677),
('jud-1-6','jud','유다서',1,6,'또 자기 지위를 지키지 아니하고 자기 처소를 떠난 천사들을 큰 날의 심판까지 영원한 결박으로 흑암에 가두셨으며',30678),
('jud-1-7','jud','유다서',1,7,'소돔과 고모라와 그 이웃 도시들도 그들과 같은 행동으로 음란하며 다른 육체를 따라 가다가 영원한 불의 형벌을 받음으로 거울이 되었느니라',30679),
('jud-1-8','jud','유다서',1,8,'그러한데 꿈꾸는 이 사람들도 그와 같이 육체를 더럽히며 권위를 업신여기며 영광을 비방하는도다',30680),
('jud-1-9','jud','유다서',1,9,'천사장 미가엘이 모세의 시체에 관하여 마귀와 다투어 변론할 때에 감히 비방하는 판결을 내리지 못하고 다만 말하되 주께서 너를 꾸짖으시기를 원하노라 하였거늘',30681),
('jud-1-10','jud','유다서',1,10,'이 사람들은 무엇이든지 그 알지 못하는 것을 비방하는도다 또 그들은 이성 없는 짐승 같이 본능으로 아는 그것으로 멸망하느니라',30682),
('jud-1-11','jud','유다서',1,11,'화 있을진저 이 사람들이여, 가인의 길에 행하였으며 삯을 위하여 발람의 어그러진 길로 몰려 갔으며 고라의 패역을 따라 멸망을 받았도다',30683),
('jud-1-12','jud','유다서',1,12,'그들은 기탄 없이 너희와 함께 먹으니 너희의 애찬에 암초요 자기 몸만 기르는 목자요 바람에 불려가는 물 없는 구름이요 죽고 또 죽어 뿌리까지 뽑힌 열매 없는 가을 나무요',30684),
('jud-1-13','jud','유다서',1,13,'자기 수치의 거품을 뿜는 바다의 거친 물결이요 영원히 예비된 캄캄한 흑암으로 돌아갈 유리하는 별들이라',30685),
('jud-1-14','jud','유다서',1,14,'아담의 칠대 손 에녹이 이 사람들에 대하여도 예언하여 이르되 보라 주께서 그 수만의 거룩한 자와 함께 임하셨나니',30686),
('jud-1-15','jud','유다서',1,15,'이는 뭇 사람을 심판하사 모든 경건하지 않은 자가 경건하지 않게 행한 모든 경건하지 않은 일과 또 경건하지 않은 죄인들이 주를 거슬러 한 모든 완악한 말로 말미암아 그들을 정죄하려 하심이라 하였느니라',30687),
('jud-1-16','jud','유다서',1,16,'이 사람들은 원망하는 자며 불만을 토하는 자며 그 정욕대로 행하는 자라 그 입으로 자랑하는 말을 하며 이익을 위하여 아첨하느니라',30688),
('jud-1-17','jud','유다서',1,17,'사랑하는 자들아 너희는 우리 주 예수 그리스도의 사도들이 미리 한 말을 기억하라',30689),
('jud-1-18','jud','유다서',1,18,'그들이 너희에게 말하기를 마지막 때에 자기의 경건하지 않은 정욕대로 행하며 조롱하는 자들이 있으리라 하였나니',30690),
('jud-1-19','jud','유다서',1,19,'이 사람들은 분열을 일으키는 자며 육에 속한 자며 성령이 없는 자니라',30691),
('jud-1-20','jud','유다서',1,20,'사랑하는 자들아 너희는 너희의 지극히 거룩한 믿음 위에 자신을 세우며 성령으로 기도하며',30692),
('jud-1-21','jud','유다서',1,21,'하나님의 사랑 안에서 자신을 지키며 영생에 이르도록 우리 주 예수 그리스도의 긍휼을 기다리라',30693),
('jud-1-22','jud','유다서',1,22,'어떤 의심하는 자들을 긍휼히 여기라',30694),
('jud-1-23','jud','유다서',1,23,'또 어떤 자를 불에서 끌어내어 구원하라 또 어떤 자를 그 육체로 더럽힌 옷까지도 미워하되 두려움으로 긍휼히 여기라',30695),
('jud-1-24','jud','유다서',1,24,'능히 너희를 보호하사 거침이 없게 하시고 너희로 그 영광 앞에 흠이 없이 기쁨으로 서게 하실 이',30696),
('jud-1-25','jud','유다서',1,25,'곧 우리 구주 홀로 하나이신 하나님께 우리 주 예수 그리스도로 말미암아 영광과 위엄과 권력과 권세가 영원 전부터 이제와 영원토록 있을지어다 아멘',30697),
('rev-1-1','rev','요한계시록',1,1,'예수 그리스도의 계시라 이는 하나님이 그에게 주사 반드시 속히 일어날 일들을 그 종들에게 보이시려고 그의 천사를 그 종 요한에게 보내어 알게 하신 것이라',30698),
('rev-1-2','rev','요한계시록',1,2,'요한은 하나님의 말씀과 예수 그리스도의 증거 곧 자기가 본 것을 다 증언하였느니라',30699),
('rev-1-3','rev','요한계시록',1,3,'이 예언의 말씀을 읽는 자와 듣는 자와 그 가운데에 기록한 것을 지키는 자는 복이 있나니 때가 가까움이라',30700),
('rev-1-4','rev','요한계시록',1,4,'요한은 아시아에 있는 일곱 교회에 편지하노니 이제도 계시고 전에도 계셨고 장차 오실 이시며 그의 보좌 앞에 있는 일곱 영과',30701),
('rev-1-5','rev','요한계시록',1,5,'또 충성된 증인으로 죽은 자들 가운데에서 먼저 나시고 땅의 임금들의 머리가 되신 예수 그리스도로 말미암아 은혜와 평강이 너희에게 있기를 원하노라 우리를 사랑하사 그의 피로 우리 죄에서 우리를 해방하시고',30702),
